import sys

import hicstraw


SOURCES = {
    "H1": "https://4dn-open-data-public.s3.amazonaws.com/fourfront-webprod/wfoutput/0abd0cb2-6e62-492f-97a8-6cd19f814e99/4DNFI2TK7L2F.hic",
    "HFF": "https://4dn-open-data-public.s3.amazonaws.com/fourfront-webprod/wfoutput/1a610d44-4811-40ba-a4ab-8391d73c1950/4DNFI18Q799K.hic",
}
CHROM = "chr12"
START = 7_600_000
END = 7_840_000


def records_by_pixel(hic, normalization, resolution):
    zoom = hic.getMatrixZoomData(
        CHROM, CHROM, "observed", normalization, "BP", resolution
    )
    records = zoom.getRecords(START, END, START, END)
    return {(r.binX, r.binY): r.counts for r in records}


def main(output_path):
    with open(output_path, "w", encoding="utf-8") as out:
        out.write("sample\tresolution\tbin1\tbin2\tKR\traw\n")
        for sample, url in SOURCES.items():
            hic = hicstraw.HiCFile(url)
            for resolution in (5000, 10000, 20000):
                kr = records_by_pixel(hic, "KR", resolution)
